After removing the `stas.statnett.no/v1alpha1` API, our controller (which uses SSA) spits out tons of error messages: `patch status: request to convert CR to an invalid group/version: stas.statnett.no/v1alpha1`.

As a workaround we added code to "fix" the managed fields with a patch in our controller. Before triggering a re-reconcile. This seems to work, but seems a bit "brutal". Sharing the code, if anyone can make use of it:

````go
func (r *StasJobReconciler) fixManagedFields(ctx context.Context, job *stasv1beta2.StasJob) (bool, error) {
	obsoleteVersionPredicate := func(mf metav1.ManagedFieldsEntry) bool {
		return mf.APIVersion == "stas.statnett.no/v1alpha1"
	}

	patchManagedFields := func() error {
		filteredManagers := slices.DeleteFunc(job.ManagedFields, obsoleteVersionPredicate)

		// Create a patch with a diff between old and new objects.
		// Just include all managed fields since that is only thing that will change
		//
		// Also include test for RV to avoid race condition
		jsonPatch := []map[string]interface{}{
			{
				"op":    "replace",
				"path":  "/metadata/managedFields",
				"value": filteredManagers,
			},
			{
				// Use "replace" instead of "test" operation so that etcd rejects with
				// 409 conflict instead of apiserver with an invalid request
				"op":    "replace",
				"path":  "/metadata/resourceVersion",
				"value": job.ResourceVersion,
			},
		}
		patch, err := json.Marshal(jsonPatch)
		if err != nil {
			return err
		}
		return r.Patch(ctx, job, client.RawPatch(types.JSONPatchType, patch))
	}

	if slices.ContainsFunc(job.ManagedFields, obsoleteVersionPredicate) {
		// At least one managed field entry contains the problematic API version
		// Remove all occurrences with a JSON patch
		err := patchManagedFields()
		if err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}
````

This code is inspired by the [code to migrate a resource from CSA to SSA](https://github.com/kubernetes/kubernetes/blob/7b802a60bd6e43ab53499e3b0a19c06f395974df/staging/src/k8s.io/client-go/util/csaupgrade/upgrade.go):
